SELECT CASE WHEN count(*) = 1 AND count_if(term = 'denim' AND site = 'A' AND n = 10 AND p50_cents = 550 AND likes_per_listing = 5.5 AND as_of IS NOT NULL) = 1
  THEN true ELSE raise_error('DBX-A1 top terms A counts repeated word once') END AS passed
FROM secondhand.market_check.top_terms('clothes', 'A', 30, 1);

SELECT CASE WHEN count(*) = 1 AND count_if(term = 'denim' AND n = 3 AND p50_cents IS NULL AND likes_per_listing IS NULL) = 1
  THEN true ELSE raise_error('DBX-A1 top terms B') END AS passed
