SELECT CASE WHEN count(*) = 1 AND count_if(site = 'A' AND kind = 'clothes' AND n_listed = 10 AND n_sold = 4 AND sold_share = 0.4 AND median_days_to_sell = 2.0 AND as_of IS NOT NULL) = 1
  THEN true ELSE raise_error('DBX-A1 sell through A') END AS passed
FROM secondhand.market_check.sell_through('clothes', 'A');

SELECT CASE WHEN count(*) = 1 AND count_if(n_listed = 3 AND n_sold IS NULL AND sold_share IS NULL AND median_days_to_sell IS NULL AND as_of IS NOT NULL) = 1
  THEN true ELSE raise_error('DBX-A1 sell through B') END AS passed
FROM secondhand.market_check.sell_through('clothes', 'B');

SELECT CASE WHEN count(*) = 1 AND count_if(site = 'all' AND n_listed = 13 AND n_sold = 5 AND abs(sold_share - 5.0 / 13) < 0.000001 AND median_days_to_sell = 2.0) = 1
  THEN true ELSE raise_error('DBX-A1 sell through all') END AS passed
FROM secondhand.market_check.sell_through('clothes', 'all');

SELECT CASE WHEN count(*) = 2 AND count_if(kind = 'clothes' AND newest_read IS NOT NULL AND ((site = 'A' AND rows = 10 AND oldest_read IS NOT NULL) OR (site = 'B' AND rows = 3 AND oldest_read IS NULL))) = 2
  THEN true ELSE raise_error('DBX-A1 coverage preserves low counts and freshness') END AS passed
FROM secondhand.market_check.coverage_now();

UPDATE secondhand.market_check.param SET value_or_hyperparams = '11' WHERE scope = '{}' AND status = 'champion';

SELECT CASE WHEN count(*) = 1 AND count_if(n = 10 AND p50_cents IS NULL) = 1
